pub fn medians(xs: List[Int], k: Int) -> List[Float] {
  var out: List[Float] = []
  if k < 1 or k > xs.len() {
    return out
  }
  for s in range(0, xs.len() - k + 1) {
    let window = xs.slice(s, s + k).sort()
    let mid = k / 2
    if k % 2 == 1 {
      out = out.push(window.get_or(mid, 0).to_float())
    } else {
      let pair_sum = window.get_or(mid - 1, 0) + window.get_or(mid, 0)
      out = out.push(pair_sum.to_float() / 2.0)
    }
  }
  return out
}
